# 金剛經：節依梵本 Vaidya 校訂本 §1–32（學界通用的 Conze 分節，非昭明三十二分）。
# 七個漢譯本逐本讀過定切點（2026-10-01）。注意：
#   T0236b CBETA 標菩提流支，實與真諦本同文（相似度 96%；T0236a 卷末普寧經局刊記已指出
#   《思溪藏》誤將真諦本重出、標作留支所譯）。
#   義淨本把「當何名此經」移到 §14 涕淚悲泣之後，故其 §13 從「頗有少法是如來所說」起。
#   笈多本照梵文語序逐字硬譯（「善實」＝須菩提），流通分在 §32 內。
