                  ("v11", "世尊言：「彼何意念？善實！所有恒伽大河沙，彼所有"), ("v12", "雖然復次時，善實！此中地分"),
                  ("v13", "命者善實，世尊邊如是言：「何名此，世尊！法本"), ("v14", "爾時，命者善實，法疾轉力淚出"),
                  ("v15", "「若復時，善實！婦女，若丈夫，若前分時"),
