# 梵本 Daśabhūmikasūtra（GRETIL，Vaidya 1967）一地一章，第 1 章含品首；藏譯 Toh 44 第 31 品＋84000 英譯（TMX 一品 2,306 句）；
# 漢譯五本：漸備一切智德經 T0285、十住經 T0286、六十華嚴 T0278 十地品、八十華嚴 T0279 十地品、十地經 T0287。
# 各本的「地」界不在同一處（八十、十住經把下一地的讚歎偈放在該地節點開頭，漸備經放在上一品節點末尾），
# 所以漢譯一律取整個十地品、用「本組起頭幾個字／下一組起頭幾個字」切出一地（DBH_BOUNDS）。
