                ("d4-07", "smṛtisaṃbodhyaṅgaṃ bhāvayati"), ("d4-08", "tacca sarvasattvasāpekṣatayā"),
                ("d4-09", "tasya khalu punarbhavanto jinaputrā bodhisattvasya asyāmar"), ("d4-10", "sa yānīmāni karmāṇyakaraṇīyāni"),
