def _h60(pin, nodes, cuts, end=None, **kw):
    src = {"work": "T0278", "nodes": nodes, "start": cuts[0][1]} | ({"end": end} if end else {})
    return {"id": "T0278", "lang": "lzh", "label": "六十華嚴", "who": f"佛馱跋陀羅譯〈{pin}〉・421 年", "src": src, "cuts": cuts, **kw}


def _h80(pin, nodes, cuts, end=None, **kw):
    src = {"work": "T0279", "nodes": nodes, "start": cuts[0][1]} | ({"end": end} if end else {})
    return {"id": "T0279", "lang": "lzh", "label": "八十華嚴", "who": f"實叉難陀譯〈{pin}〉・699 年", "src": src, "cuts": cuts, **kw}


def _hx(work, label, who, cuts, end=None, nodes=None, **kw):
    """別行本：多半只對應本品的一段，不掛目錄錨點（anchor_nodes=[]），閱讀器按段落範圍載入。"""
    src = {"work": work, "start": cuts[0][1], "anchor_nodes": []} | ({"end": end} if end else {}) | ({"nodes": nodes} if nodes else {})
    return {"id": work, "lang": "lzh", "label": label, "who": who, "src": src, "cuts": cuts, **kw}


