# ── 解深密經第二至十章：藏譯 Toh 106 十章（84000 TMX 章尾句「This was the chapter of…」）為骨架 ──
# 玄奘 T0676 把一至四章併為〈勝義諦相品〉，五至十章＝心意識相…如來成所作事；流支 T0675 一章一品（品號＝章號＋1）；
# 真諦《解節經》T0677 只譯一至四章；求那跋陀羅 T0678＝第九章、T0679＝第十章。
_SN_TMX = [0, 66, 100, 154, 201, 243, 301, 533, 881, 1135, 1289]   # 第 n 章 TMX 起點；末為迄


def _sn(k, title, intro, units, lines, zh):
    a, b = _SN_TMX[k - 1], _SN_TMX[k]
    SETS[f"samdhinirmocana-{k}"] = {
        "title": f"解深密經・{title}", "family": "bo", "extra_works": ["DKtoh0106"], "intro": intro, "units": units,
        "versions": [{"id": side, "lang": side, "label": lab, "who": who, "src": {"tmx": "toh106", "side": side, "from": a, "to": b},
                      "lines": [(u, n - a) for u, n in lines]}
                     for side, lab, who in [("bo", "藏譯", "德格版 Toh 106・84000 翻譯記憶"), ("en", "84000 英譯", "譯自藏譯・與藏文逐句對齊")]]
                    + zh}


def _snz(work, src, cuts):
    lab, who = {"T0675": ("流支本", "菩提流支譯《深密解脫經》・514 年"), "T0677": ("真諦本", "真諦譯《解節經》・約 560 年"),
                "T0676": ("玄奘本", "玄奘譯《解深密經》・647 年"),
                "T0678": ("相續解脫地波羅蜜了義經", "求那跋陀羅譯・五世紀"), "T0679": ("相續解脫如來所作隨順處了義經", "求那跋陀羅譯・五世紀")}[work]
    return {"id": work, "lang": "lzh", "label": lab, "who": who, "src": {"work": work, "start": cuts[0][1]} | src, "cuts": cuts}


