_SUV_ZH = {"T0663": ("曇無讖本", "曇無讖譯《金光明經》・五世紀初"), "T0664": ("合部本", "寶貴合《合部金光明經》・597 年"),
           "T0665": ("義淨本", "義淨譯《金光明最勝王經》・703 年")}


def _suv(k, title, intro, units, sa, en, zh):
    """sa＝(start, end, cuts)；en＝[(義段, TMX 絕對行號)]；zh＝[(work, nodes, cuts, 其他 src 欄)]。"""
    a, b = _SUV_TMX[k - 1], _SUV_TMX[k]
    st, ed, sc = sa
    SETS[f"suvarnaprabhasa-c{k:02d}"] = {
        "title": f"金光明經・{title}", "family": "sa", "extra_works": [], "intro": intro, "units": units,
        "versions": [{"id": "sa", "lang": "sa", "label": "梵本", "who": "Nobel 校訂本・GRETIL",
                      "src": {"gretil": "sa_suvarNaprabhAsasUtra", "start": st} | ({"end": ed} if ed else {}), "cuts": sc}]
                    + [{"id": side, "lang": side, "label": lab, "who": who, "src": {"tmx": "toh557", "side": side, "from": a, "to": b},
                        "lines": [(u, n - a) for u, n in en]}
                       for side, lab, who in [("bo", "藏譯", "德格版 Toh 557・84000 翻譯記憶"), ("en", "84000 英譯", "譯自藏譯・與藏文逐句對齊")]]
                    + [{"id": w, "lang": "lzh", "label": _SUV_ZH[w][0], "who": _SUV_ZH[w][1],
                        "src": {"work": w, "nodes": nodes, "start": cuts[0][1]} | {x: y for x, y in (extra or {}).items() if x != "reorder"},
                        "cuts": cuts} | ({"reorder": True} if (extra or {}).get("reorder") else {})
                       for w, nodes, cuts, extra in zh]}


