    a, b = tmx
    SETS[f"suvarnaprabhasa-{slug}"] = {
        "title": f"金光明經・{title}", "family": "sa", "extra_works": [], "intro": intro, "units": units,
        "versions": [{"id": side, "lang": side, "label": lab, "who": who, "src": {"tmx": "toh556", "side": side, "from": a, "to": b},
                      "lines": [(u, n - a) for u, n in en]}
                     for side, lab, who in [("bo", "藏譯", "德格版 Toh 556（二十九章本）・84000"), ("en", "84000 英譯", "譯自藏譯・與藏文逐句對齊")]]
                    + [{"id": w, "lang": "lzh", "label": _SUV_ZH[w][0], "who": _SUV_ZH[w][1],
                        "src": {"work": w, "nodes": nodes, "start": cuts[0][1]}, "cuts": cuts} for w, nodes, cuts in zh]}


