     {'T1564': ('中論觀十二因緣品第二十六（九偈）', [('m01', '問曰：汝以摩'), ('m02', '以諸行因緣，'), ('m03', '名色增長故，'), ('m05', '因於六觸故，'), ('m06', '以因三受故，'), ('m07', '若取者不取，'), ('m08', '從有而有生，'), ('m09', '如是等諸事，'), ('m10', '是謂為生死，'), ('m11', '以是事滅故，')], False), 'T1566': ('般若燈論釋觀世諦緣起品第二十六', [('m01', '釋曰：今此品'), ('m02', '「以諸行因緣'), ('m03', '「從於名色體'), ('m04', '「因彼眼與色'), ('m05', '「彼色識眼等'), ('m06', '「受為起愛緣'), ('m07', '「由取諸有故'), ('m08', '「五陰是有體'), ('m09', '「愁及勞倦等'), ('m10', '「是謂為生死'), ('m11', '「無明若已斷'), ('m12', '「一一支滅者')], False)},
