# 梵本第十品〈Sagāthakam〉884 頌＝實叉難陀〈偈頌品〉（約 668 頌）＝菩提流支〈總品〉（約 910 頌）；求那跋陀羅無。
# 三本頌序大體一致：實叉難陀略去與前九品重出之偈，菩提流支略去開頭讚佛偈而偶有增頌。依梵本頌號每十來頌一節、約百頌一組；
# 各節漢譯起點由 scratchpad 的 ggen.py 依頌序取最短唯一起頭字（列＝義段、梵頌號、實叉頌序、菩提流支頌序、標籤、三本切點；頌序 0＝該本無）。
_LKG_GROUPS: list[list[tuple]] = []


def _lkg(k, intro, rows, nxt=None):
    """rows＝ggen 產出的列；nxt＝下一組第一列（取其切點當本組 end）。"""
    ends = [r[1] - 1 for r in rows[1:]] + [(nxt[1] - 1) if nxt else 884]
    units = [(r[0], r[4] if r[1] > 884 else f"10.{r[1]}–{e} {r[4]}") for r, e in zip(rows, ends)]
    sa_cuts = [(r[0], r[5]) for r in rows if r[5]]
    sik = [(r[0], r[6]) for r in rows if r[6]]
    bod = [(r[0], r[7]) for r in rows if r[7]]
    sa_src = ({"after": f"Lank_10.{rows[0][1] - 1} //"} if k > 1 else {}) | {"start": sa_cuts[0][1]} | ({"end": nxt[5]} if nxt else {})
    zh = [("T0672", ["大乘入楞伽經偈頌品第十之初"], sik, ({"end": nxt[6]} if nxt else {}) | ({} if k == 1 else {"anchor_nodes": []})),
          ("T0671", ["總品第十八之一"], bod, ({"end": nxt[7]} if nxt else {}) | ({} if k == 1 else {"anchor_nodes": []}))]
    _lk(f"lankavatara-c10-{k}", f"偈頌品（{'一二三四五六七八九十'[k - 1]}）10.{rows[0][1]}–{(nxt[1] - 1) if nxt else 884}",
        intro, units, (sa_src, sa_cuts), zh)


