# ── 藏譯系候選（東北目錄 ≥2 漢譯＋84000 TMX）逐部人工對齊 ─────────────────────────────
def _bo(toh, a, b, lines, who):
    """藏譯＋84000 英譯兩欄（同一組 TMX 句號）。who＝藏譯那欄的說明。"""
    return [{"id": side, "lang": side, "label": lab, "who": w, "src": {"tmx": toh, "side": side, "from": a, "to": b}, "lines": lines}
            for side, lab, w in [("bo", "藏譯", who), ("en", "84000 英譯", "譯自藏譯・與藏文逐句對齊")]]


def _z(work, label, who, cuts, **src):
    """不分品的短經漢譯：從第一刀那幾個字起取到卷末（end 截止）。"""
    return {"id": work, "lang": "lzh", "label": label, "who": who, "src": {"work": work, "start": cuts[0][1]} | src, "cuts": cuts}


